-- Creates the idempotency_records table.
--
-- One row per idempotency scope: a merchant, an operation, and the key the
-- client sent. A command claims its scope by inserting the row in progress,
-- and completes it with the response it returns, so a retry with the same key
-- and the same request replays that response instead of running the command
-- again. Timestamps have no database default: the application supplies them
-- from its injected clock. Identifiers are UUIDs generated by the application.

CREATE TABLE idempotency_records (
  id uuid NOT NULL,
  merchant_id uuid NOT NULL,
  operation varchar(64) NOT NULL,
  -- text with a CHECK instead of varchar(255): varchar silently cuts trailing
  -- spaces beyond its bound, which would merge two distinct keys into one.
  idempotency_key text NOT NULL,
  request_fingerprint varchar(64) NOT NULL,
  operation_id uuid NOT NULL,
  status varchar(20) NOT NULL,
  response_status_code smallint,
  -- json instead of jsonb: json keeps the exact text it was given, so a replay
  -- returns the body with its original key order.
  response_body json,
  created_at timestamptz NOT NULL,
  completed_at timestamptz,
  expires_at timestamptz NOT NULL,
  CONSTRAINT idempotency_records_pkey PRIMARY KEY (id),
  CONSTRAINT idempotency_records_merchant_id_fkey FOREIGN KEY (merchant_id) REFERENCES merchants (id),
  CONSTRAINT idempotency_records_scope_key UNIQUE (merchant_id, operation, idempotency_key),
  -- Upper snake case code chosen by the command, for example CREATE_PAYMENT_INTENT.
  CONSTRAINT idempotency_records_operation_check CHECK (operation ~ '^[A-Z][A-Z0-9_]{0,63}$'),
  -- 1 to 255 visible ASCII characters: no spaces, control characters, or
  -- characters outside ASCII.
  CONSTRAINT idempotency_records_idempotency_key_check CHECK (idempotency_key ~ '^[!-~]{1,255}$'),
  -- SHA-256 digest in lowercase hexadecimal.
  CONSTRAINT idempotency_records_request_fingerprint_check CHECK (request_fingerprint ~ '^[0-9a-f]{64}$'),
  CONSTRAINT idempotency_records_status_check CHECK (status IN ('IN_PROGRESS', 'COMPLETED')),
  CONSTRAINT idempotency_records_response_status_code_check CHECK (response_status_code BETWEEN 100 AND 599),
  CONSTRAINT idempotency_records_response_body_check CHECK (
    json_typeof(response_body) = 'object' AND octet_length(response_body::text) <= 65536
  ),
  -- A record in progress has no response yet; a completed record has all of it.
  CONSTRAINT idempotency_records_status_response_check CHECK (
    (
      status = 'IN_PROGRESS'
      AND response_status_code IS NULL
      AND response_body IS NULL
      AND completed_at IS NULL
    )
    OR (
      status = 'COMPLETED'
      AND response_status_code IS NOT NULL
      AND response_body IS NOT NULL
      AND completed_at IS NOT NULL
    )
  ),
  CONSTRAINT idempotency_records_expires_at_check CHECK (expires_at > created_at)
);

COMMENT ON TABLE idempotency_records IS 'Idempotency claims of merchant commands, one per merchant, operation, and client key, with the response to replay once the command has completed.';
COMMENT ON COLUMN idempotency_records.request_fingerprint IS 'SHA-256 of the canonical encoding of the operation and the validated request. It excludes the idempotency key, the correlation ID, and other transport metadata.';
COMMENT ON COLUMN idempotency_records.operation_id IS 'Stable identifier of the business operation that the command performs under this key, supplied by the command when it claims the key.';
COMMENT ON COLUMN idempotency_records.response_body IS 'Response body replayed to a retry. It must never hold secrets, API keys, payment tokens, or payment credentials.';
COMMENT ON COLUMN idempotency_records.expires_at IS 'When the record becomes eligible for removal. Until a record is removed, its expiry does not change how claims of its scope are answered.';

-- The scope, the fingerprint, the operation ID, and the creation time never
-- change, and a completed record never changes at all, so a replay always
-- returns the response that was stored first.
CREATE FUNCTION idempotency_records_reject_invalid_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.merchant_id, NEW.operation, NEW.idempotency_key,
      NEW.request_fingerprint, NEW.operation_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.merchant_id, OLD.operation, OLD.idempotency_key,
      OLD.request_fingerprint, OLD.operation_id, OLD.created_at) THEN
    RAISE EXCEPTION 'idempotency_records: the scope and identity of a record cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status = 'COMPLETED' THEN
    RAISE EXCEPTION 'idempotency_records: a completed record cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER idempotency_records_restrict_update
BEFORE UPDATE ON idempotency_records
FOR EACH ROW
EXECUTE FUNCTION idempotency_records_reject_invalid_update();
